import type { Metadata, Viewport } from "next";
import localFont from "next/font/local";
import "../globals.css";
import { getProjects, getServices, getSettings } from "@/lib/data";
import { buildMenuGroups, buildSearchItems } from "@/lib/search";
import { DEFAULT_THEME, INTRO_SCRIPT, THEME_BAR, THEME_SCRIPT } from "@/lib/theme";
import { siteUrl } from "@/lib/utils";
import { Header } from "@/components/site/Header";
import { Logo } from "@/components/site/Logo";
import { Footer } from "@/components/site/Footer";
import { Dock } from "@/components/site/Dock";
import { ScrollTop } from "@/components/site/ScrollTop";
import { MenuProvider } from "@/components/site/MenuContext";
import { MenuOverlay } from "@/components/site/MenuOverlay";
import { Reveal } from "@/components/motion/Reveal";
import { Cursor } from "@/components/motion/Cursor";
import { BrandGradientDefs } from "@/components/site/SocialLinks";
import { IntroLoader } from "@/components/motion/IntroLoader";
import { JsonLd } from "@/components/site/JsonLd";
import { siteSchema } from "@/lib/schema";

/** Outfit, the Opsiogen typeface (SIL OFL), self-hosted as one variable file covering weights 100–900. */
const outfit = localFont({
  src: "../../fonts/Outfit-Variable.woff2",
  weight: "100 900",
  variable: "--font-outfit",
  display: "swap",
});

/** A verification code pasted in Studio, whole tag or just its content value. */
const verificationCode = (value?: string | null) => {
  const text = value?.trim();
  return text ? (text.match(/content=["']([^"']+)["']/)?.[1] ?? text) : undefined;
};

export async function generateMetadata(): Promise<Metadata> {
  const settings = await getSettings();
  const image = settings.seo.image;
  const google = verificationCode(settings.seo.googleVerification);
  const bing = verificationCode(settings.seo.bingVerification);
  return {
    metadataBase: new URL(siteUrl()),
    title: { default: settings.seo.title, template: `%s | ${settings.siteTitle}` },
    description: settings.seo.description,
    applicationName: settings.siteTitle,
    openGraph: {
      type: "website",
      siteName: settings.siteTitle,
      title: settings.seo.title,
      description: settings.seo.description,
      images: image ? [{ url: image.url, width: image.width, height: image.height, alt: image.alt }] : undefined,
    },
    twitter: { card: "summary_large_image" },
    ...((google || bing) && {
      verification: { ...(google && { google }), ...(bing && { other: { "msvalidate.01": bing } }) },
    }),
  };
}

export const viewport: Viewport = {
  themeColor: THEME_BAR[DEFAULT_THEME],
};

/** `modal` is the @modal slot: a project opened from a link shows there, full screen, over the page. */
export default async function SiteLayout({ children, modal }: LayoutProps<"/">) {
  const [settings, projects, services] = await Promise.all([getSettings(), getProjects(), getServices()]);
  const searchItems = buildSearchItems(projects, services);
  const groups = buildMenuGroups(services);
  return (
    // The head scripts change <html> before React hydrates, hence suppressHydrationWarning.
    <html lang="en" data-theme={DEFAULT_THEME} className={outfit.variable} suppressHydrationWarning>
      <head>
        {/* CMS images come from Sanity's CDN: open the connection early. */}
        <link rel="preconnect" href="https://cdn.sanity.io" />
        {/* Applies the theme (dark unless the visitor chose light) before the first paint. */}
        <script dangerouslySetInnerHTML={{ __html: THEME_SCRIPT }} />
        {/* Decides whether the first-visit intro plays, and starts it. */}
        <script dangerouslySetInnerHTML={{ __html: INTRO_SCRIPT }} />
        {/* Without scripts nothing marks the page loaded: show the client logos straight away. */}
        <noscript>
          <style>{`.client-logo{visibility:visible;-webkit-mask:var(--logo) center/contain no-repeat;mask:var(--logo) center/contain no-repeat}`}</style>
        </noscript>
      </head>
      <body>
        <JsonLd items={siteSchema(settings, services)} />
        <BrandGradientDefs />
        <IntroLoader />
        <MenuProvider>
          <a
            href="#main"
            className="sr-only z-[60] rounded-[var(--radius-btn)] bg-ink px-4 py-3 text-on-ink focus:not-sr-only focus:fixed focus:left-4 focus:top-4"
          >
            Skip to content
          </a>
          <Header settings={settings} groups={groups} searchItems={searchItems} />
          <main id="main" tabIndex={-1} className="outline-none">
            {children}
          </main>
          {modal}
          <Footer settings={settings} services={services} />
          <Dock menu={settings.menu} button={settings.dockButton} />
          <ScrollTop />
          <MenuOverlay
            menu={settings.menu}
            button={settings.headerButton}
            wordmark={<Logo logo={settings.logo} name={settings.siteTitle} large />}
            searchItems={searchItems}
            groups={groups}
            email={settings.email}
            socialLinks={settings.socialLinks}
          />
          <Reveal />
          <Cursor />
        </MenuProvider>
      </body>
    </html>
  );
}
